
CREATE TABLE `QuickSqlDefaultsRow` (`Id` INT AUTO_INCREMENT NOT NULL, `Label` VARCHAR(16) NULL DEFAULT '新行', `Active` TINYINT(1) NOT NULL DEFAULT 1, `Reserved` INT NOT NULL DEFAULT 7, `Ratio` DOUBLE NOT NULL DEFAULT 0.5, `Amount` DECIMAL(18,4) NOT NULL, `Bare` TEXT NULL, CONSTRAINT `PK_QuickSqlDefaultsRow` PRIMARY KEY (`Id`)) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4
